#!/usr/bin/env python3
"""Genera la web estática a partir de data/content.json. Solo requiere Python 3."""
from pathlib import Path
from html import escape as esc
from datetime import date
import json
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'data/content.json').read_text())
B=D['brand']; ISLANDS={x['id']:x for x in D['islands']}; SPORTS={x['id']:x for x in D['sports']}
NAV=[('index.html','Inicio'),('islas.html','Islas'),('spots.html','Spots'),('modalidades.html','Modalidades'),('prevision.html','Previsión'),('eventos.html','Eventos'),('blog.html','Noticias'),('multimedia.html','Multimedia')]

def image(name,alt,cls='',lazy=True):
    return f'<img src="assets/img/{esc(name)}" alt="{esc(alt)}" class="{cls}" loading="{"lazy" if lazy else "eager"}" decoding="async">'
def button(url,label,cls='primary',external=False):
    return f'<a class="button {cls}" href="{esc(url)}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{esc(label)}</a>'
def intro(kicker,title,text='',dark=False):
    return f'<section class="page-intro {"intro-dark" if dark else ""}"><div class="container"><p class="eyebrow">{kicker}</p><h1>{title}</h1>'+ (f'<p class="intro-text">{text}</p>' if text else '')+'</div></section>'
def heading(label,title,link=None):
    return f'<div class="section-heading"><div><p class="eyebrow">{label}</p><h2>{title}</h2></div>'+ (f'<a class="underlink" href="{link[0]}">{link[1]}</a>' if link else '')+'</div>'
def island_card(i):
    count=sum(s['island']==i['id'] for s in D['spots'])
    return f'<a class="island-card" href="islas/{i["id"]}.html">{image(i["image"],"Paisaje de "+i["name"])}<div><span class="card-caption">{str(count)+" spots en la guía" if count else "Explorar el territorio"}</span><h3>{i["name"]}</h3><p>{i["title"]}</p></div></a>'
def spot_card(s):
    return f'<article class="spot-card" data-island="{s["island"]}" data-sports="{" ".join(s["sports"])}" data-level="{s["group"]}" data-name="{esc(s["name"].lower())}"><div class="card-meta"><span>{ISLANDS[s["island"]]["name"]}</span><span>{s["bottom"]}</span></div><h3><a href="spots/{s["id"]}.html">{s["name"]}</a></h3><p>{s["text"]}</p><div class="tag-row">'+''.join(f'<span class="tag">{SPORTS[x]["name"]}</span>' for x in s['sports'])+f'</div><p class="level">{s["level"]}</p><div class="card-actions"><a class="underlink" href="spots/{s["id"]}.html">Ver ficha</a><button class="map-link" data-map-spot="{s["id"]}">Ver en mapa</button></div></article>'
def event_card(e):
    start=date.fromisoformat(e['start']) if e['start'] else None
    day=str(start.day) if start else '2027' if e['id']=='lwf2027' else '—'
    month=['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'][start.month-1] if start else 'PROYECTO' if e['id']=='lwf2027' else 'CALENDARIO'
    return f'<article class="event-card" data-island="{e["island"]}" data-sport="{e["sport"]}"><div class="event-date"><span>{day}</span><small>{month}</small></div><div><div class="card-meta"><span>{e["category"]}</span><span class="event-state" data-start="{e["start"] or ""}" data-end="{e["end"] or ""}">{e["status"]}</span></div><h3><a href="eventos/{e["id"]}.html">{e["name"]}</a></h3><p class="event-place">{e["place"]} · {e["dateLabel"]}</p><p>{e["text"]}</p><a class="underlink" href="eventos/{e["id"]}.html">Ver información</a></div></article>'
def source(url,label='Consultar fuente oficial'):
    return f'<a class="source-link" href="{esc(url)}" target="_blank" rel="noopener noreferrer">{label}</a>'
def select_options(items):
    return ''.join(f'<option value="{x["id"]}">{x["name"]}</option>' for x in items)
def map_block():
    return '<div class="map-section"><div class="map-heading"><h2>El archipiélago, spot a spot.</h2><p>Ubicaciones orientativas. Consulta cada ficha para conocer el entorno.</p></div><div id="spot-map" aria-label="Mapa de spots de Canarias"></div><p id="map-status" class="micro" role="status"></p></div>'

def page(path,title,body,description,active=None,map_enabled=False):
    p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True)
    prefix='../'*len(Path(path).parts[:-1])
    nav=''.join(f'<a href="{prefix}{f}"'+(' aria-current="page"' if f==active else '')+f'>{label}</a>' for f,label in NAV)
    menu=''.join(f'<a href="{prefix}{f}">{label}</a>' for f,label in [('about.html','Sobre nosotros'),('proyectos.html','ANSA y LWF2027'),('campeonatos.html','Campeonatos'),('contact.html','Contacto')])
    body=body.replace('href="assets/','href="'+prefix+'assets/').replace('src="assets/','src="'+prefix+'assets/')
    for folder in ['islas/','spots/','eventos/','articulos/']:
        body=body.replace('href="'+folder,'href="'+prefix+folder)
    for filename in ['index','islas','spots','modalidades','prevision','eventos','campeonatos','blog','multimedia','about','contact','proyectos','fuentes','privacidad']:
        body=body.replace(f'href="{filename}.html',f'href="{prefix}{filename}.html')
    absolute='https://'+B['domain']+'/'+path
    structured={'@context':'https://schema.org','@type':'WebPage','name':title+' · Surf Islas Canarias','url':absolute,'description':description,'inLanguage':'es'}
    html=f'''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#082d43"><meta name="description" content="{esc(description)}"><title>{esc(title)} · Surf Islas Canarias</title><meta property="og:title" content="{esc(title)} · Surf Islas Canarias"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="website"><link rel="canonical" href="{absolute}"><link rel="icon" type="image/png" href="{prefix}assets/img/logo.png"><link rel="stylesheet" href="{prefix}assets/css/style.css">{f'<link rel="stylesheet" href="{prefix}assets/vendor/leaflet/leaflet.css"><script src="{prefix}assets/vendor/leaflet/leaflet.js" defer></script>' if map_enabled else ''}<script type="application/ld+json">{json.dumps(structured,ensure_ascii=False)}</script><script src="{prefix}assets/js/content.js" defer></script><script src="{prefix}assets/js/app.js" defer></script></head>
<body data-root="{prefix or './'}"><a class="skip-link" href="#contenido">Saltar al contenido</a><div class="topbar"><div class="container"><span>CANARIAS · OLAS · VIENTO · COMUNIDAD</span><a href="{B['instagram']}" target="_blank" rel="noopener noreferrer">@surfislascanarias</a></div></div><header class="site-header"><div class="container header-inner"><a class="brand" href="{prefix}index.html"><img src="{prefix}assets/img/logo.png" width="58" height="58" alt=""><span>SURF ISLAS<small>CANARIAS</small></span></a><nav class="desktop-nav" aria-label="Navegación principal">{nav}</nav><button class="menu-button" aria-controls="site-menu" aria-expanded="false" aria-label="Abrir menú">Menú <span aria-hidden="true">☰</span></button></div><nav id="site-menu" class="site-menu container" aria-label="Todas las secciones" hidden>{nav}{menu}</nav></header><main id="contenido">{body}</main>
<section class="community-cta"><div class="container"><div><p class="eyebrow">LA COMUNIDAD SIGUE EN EL AGUA</p><h2>Lo nuestro es el mar.</h2><p>Reports, eventos y cultura de las islas. Nos vemos en Surf Islas Canarias.</p></div><a class="button white" href="{B['instagram']}" target="_blank" rel="noopener noreferrer">Seguir en Instagram</a></div></section><footer class="site-footer"><div class="container footer-grid"><div><a class="brand footer-brand" href="{prefix}index.html"><img src="{prefix}assets/img/logo.png" alt="" width="56" height="56"><span>SURF ISLAS<small>CANARIAS</small></span></a><p>La comunidad canaria de surf.<br>Olas, viento y respeto por el territorio.</p></div><div><h3>Explora</h3><a href="{prefix}islas.html">Las ocho islas</a><a href="{prefix}spots.html">Spots y mapa</a><a href="{prefix}prevision.html">Previsión</a><a href="{prefix}modalidades.html">Modalidades</a></div><div><h3>Comunidad</h3><a href="{prefix}about.html">Sobre nosotros</a><a href="{prefix}proyectos.html">ANSA y LWF2027</a><a href="{prefix}campeonatos.html">Campeonatos</a><a href="{prefix}contact.html">Contacto y colaboración</a></div><div><h3>Encuéntranos</h3><a href="{B['instagram']}" target="_blank" rel="noopener noreferrer">Instagram</a><a href="{B['facebook']}" target="_blank" rel="noopener noreferrer">Facebook</a><a href="{B['tiktok']}" target="_blank" rel="noopener noreferrer">TikTok</a></div></div><div class="container footer-bottom"><span>© <span class="year">2026</span> Surf Islas Canarias</span><div><a href="{prefix}fuentes.html">Fuentes y créditos</a><a href="{prefix}privacidad.html">Privacidad</a></div></div></footer></body></html>'''
    p.write_text(html,encoding='utf-8')

home=f'''<section class="hero"><img class="hero-photo" src="assets/img/hero.webp" alt="Una ola rompe en El Confital, Gran Canaria" fetchpriority="high" width="1800" height="1197"><div class="container hero-content"><p class="eyebrow">SURF ISLAS CANARIAS</p><h1>EL ATLÁNTICO<br>SE VIVE AQUÍ<span>.</span></h1><p>Olas, viento y una comunidad que mira al mar.<br>Descubre el surf de nuestras islas.</p><div class="actions">{button('spots.html','Explorar spots','orange')}{button('prevision.html','Consultar previsión','glass')}</div></div><div class="hero-caption container"><span>EL CONFITAL · GRAN CANARIA</span><span>28° N · 15° O</span></div></section>
<div class="quick-nav container"><a href="islas.html"><strong>08</strong><span>Islas para descubrir</span></a><a href="modalidades.html"><strong>09</strong><span>Formas de vivir el mar</span></a><a href="spots.html"><strong>13</strong><span>Spots en la guía</span></a><a href="eventos.html"><strong>Agenda</strong><span>Encuentra la próxima cita</span></a></div>
<section class="section container">{heading('UN ARCHIPIÉLAGO. MUCHAS FORMAS DE SENTIRLO.','Elige tu isla.',('islas.html','Ver las ocho islas'))}<div class="island-grid">{''.join(island_card(i) for i in D['islands'][:4])}</div><div class="island-shortcuts">{''.join(f'<a href="islas/{i["id"]}.html">{i["name"]}</a>' for i in D['islands'][4:])}</div></section>
<section class="section section-pale"><div class="container">{heading('EN EL RADAR','El mar también reúne.',('eventos.html','Explorar la agenda'))}<div class="home-event"><div class="event-feature"><span class="tag tag-orange">17–31 OCTUBRE 2026</span><h2>Frontón King.<br>La cita del bodyboard.</h2><p>Gáldar vuelve a mirar hacia El Frontón. Consulta la ventana de competición y sigue las jornadas desde sus canales oficiales.</p>{button('eventos/fronton-king-2026.html','Guía del evento')}</div><div class="lwf-feature"><p class="eyebrow">PROYECTO PROPIO · HORIZONTE 2027</p><h3>Lanzarote<br>Wind Festival.</h3><p>Deporte náutico, inclusión y sostenibilidad. Una propuesta de ANSA en desarrollo.</p><a class="underlink" href="proyectos.html#lwf2027">Conocer el proyecto</a></div></div></div></section>
<section class="section container">{heading('SURF. BODYBOARD. VIENTO.','Encuentra tu manera.',('modalidades.html','Todas las modalidades'))}<div class="sport-band">{''.join(f'<a href="modalidades.html#{s["id"]}"><span>{s["tag"]}</span><h3>{s["name"]}</h3></a>' for s in D['sports'][:6])}</div></section>
<section class="section container split-about"><div>{image('instagram-brand.png','Identidad de Surf Islas Canarias','brand-poster')}</div><div><p class="eyebrow">DESDE LAS ISLAS, PARA SU COMUNIDAD</p><h2>Más que una previsión.<br>Una forma de conectar.</h2><p>Compartimos spots, eventos, imágenes y cultura del mar con una mirada canaria, cercana y respetuosa. Surf Islas Canarias conecta la comunicación deportiva con los proyectos de ANSA.</p><div class="actions">{button('about.html','Conoce Surf Islas Canarias','outline')}<a class="underlink" href="contact.html">Colabora con la comunidad</a></div></div></section>'''
page('index.html','Inicio',home,'La comunidad de Surf Islas Canarias: descubre islas, spots, previsión de oleaje, modalidades, eventos y proyectos vinculados al mar.','index.html')

page('islas.html','Las ocho islas',intro('DESCUBRE EL ARCHIPIÉLAGO','Ocho islas.<br>Un mismo océano.','Cada isla tiene su ritmo, su costa y su forma de acercarse al Atlántico.')+f'<section class="section container"><div class="island-grid all-islands">{"".join(island_card(i) for i in D["islands"])}</div></section>','Guía de las ocho Islas Canarias y su relación con el surf, los deportes náuticos y el territorio.','islas.html')
for i in D['islands']:
    spots=[s for s in D['spots'] if s['island']==i['id']]
    body=f'<section class="island-hero"><img src="assets/img/{i["image"]}" alt="Paisaje de {i["name"]}"><div class="container"><p class="eyebrow">ISLAS CANARIAS</p><h1>{i["name"]}</h1><p>{i["title"]}</p></div></section><section class="section container"><div class="island-intro"><h2>Conoce su costa.</h2><p>{i["text"]}</p></div>'+ (f'<div class="spot-grid">{"".join(spot_card(s) for s in spots)}</div>' if spots else '<div class="info-panel"><h3>Explora con información local.</h3><p>Esta guía todavía no incluye fichas verificadas de spots en esta isla. Consulta los servicios deportivos y la información turística local para planificar tu actividad.</p>'+source('https://www.holaislascanarias.com/','Información turística oficial')+'</div>')+f'<div class="actions island-bottom">{button("spots.html?isla="+i["id"],"Ver el directorio","outline")}{button("islas.html","Volver a las islas","text-button")}</div></section>'
    page(f'islas/{i["id"]}.html',i['name'],body,i['text'],'islas.html')
    legacy_name=i['legacy']
    if legacy_name!=i['id']:
        page(f'islas/{legacy_name}.html',i['name'],body,i['text'],'islas.html')

filters=f'''<form id="spot-filters" class="filter-bar" aria-label="Filtrar spots"><label>Buscar spot<input type="search" id="spot-search" placeholder="Famara, El Confital…"></label><label>Isla<select id="spot-island"><option value="">Todas las islas</option>{select_options(D['islands'])}</select></label><label>Modalidad<select id="spot-sport"><option value="">Todas</option>{select_options(D['sports'])}</select></label><label>Nivel orientativo<select id="spot-level"><option value="">Todos</option><option value="iniciacion">Iniciación acompañada</option><option value="intermedio">Intermedio</option><option value="experto">Experto</option></select></label><button type="reset" class="button outline">Limpiar</button></form>'''
body=intro('DIRECTORIO DE SPOTS','Encuentra tu próximo entorno.','Busca por isla, modalidad y nivel. La selección del spot también depende de las condiciones del día.')+f'<section class="section container">{filters}<p id="spot-count" class="result-count" aria-live="polite">13 spots en la guía</p><div class="spot-grid" id="spot-results">{"".join(spot_card(s) for s in D["spots"])}</div><div id="spot-empty" class="info-panel" hidden><h2>No hay fichas con esos filtros.</h2><p>Prueba otra isla o modalidad. La guía irá creciendo con información contrastada.</p></div>{map_block()}<p class="editorial-note">Los niveles son orientativos y no garantizan condiciones aptas. Si empiezas, aprende con una escuela y sigue las indicaciones locales.</p></section>'
page('spots.html','Spots y mapa',body,'Busca spots de surf, bodyboard y deportes de viento en Canarias. Directorio con filtros, fichas y mapa interactivo.','spots.html',True)
for s in D['spots']:
    body=intro(ISLANDS[s['island']]['name'].upper(),s['name'],s['text'],True)+f'<section class="section container spot-detail"><div><p class="eyebrow">FICHA DEL SPOT</p><dl class="facts"><div><dt>Isla</dt><dd>{ISLANDS[s["island"]]["name"]}</dd></div><div><dt>Modalidades</dt><dd>{", ".join(SPORTS[k]["name"] for k in s["sports"])}</dd></div><div><dt>Nivel orientativo</dt><dd>{s["level"]}</dd></div><div><dt>Entorno</dt><dd>{s["bottom"]}</dd></div></dl><p>Comprueba el oleaje, el viento, el acceso y las indicaciones locales antes de entrar. El nivel indicado depende de las condiciones y de tu experiencia.</p><div class="actions">{button("prevision.html?spot="+s["id"],"Consultar previsión")}{button("spots.html?spot="+s["id"],"Ver en el mapa","outline")}</div></div><aside class="info-panel"><h2>Conoce el entorno.</h2><p>Información contrastada con fuentes turísticas o de la organización correspondiente. Coordenadas orientativas de la zona, no un punto de entrada al agua.</p>{source(s["source"])}<p class="micro">Ficha revisada: 8 octubre 2026</p></aside></section>'
    page(f'spots/{s["id"]}.html',s['name'],body,s['text'],'spots.html')

sporthtml=''.join(f'<article class="sport-detail" id="{s["id"]}"><div class="sport-number">{str(n+1).zfill(2)}</div><div><p class="eyebrow">{s["tag"]}</p><h2>{s["name"]}</h2><p class="lead">{s["text"]}</p><p>{s["detail"]}</p><a class="underlink" href="spots.html?modalidad={s["id"]}">Explorar el directorio</a></div></article>' for n,s in enumerate(D['sports']))
page('modalidades.html','Modalidades',intro('NUEVE FORMAS DE VIVIR EL MAR','Encuentra tu modalidad.','Olas, viento, remo e hidroalas. Conoce lo que hace distinta a cada forma de entrar en el agua.')+f'<section class="section container"><nav class="chip-list" aria-label="Elegir modalidad">{"".join(f"<a href=\"#{s['id']}\">{s['name']}</a>" for s in D["sports"])}</nav>{sporthtml}</section>','Surf, bodyboard, longboard, SUP, windsurf, kitesurf, wingfoil, surf foil y skimboard en Canarias.','modalidades.html')

body=intro('OLEAJE Y VIENTO','Mira el mar antes de salir.','Consulta la previsión del entorno de un spot. Datos de modelo, con hora de Canarias.')+f'''<section class="section container"><form id="forecast-form" class="forecast-toolbar"><label>Elige un spot<select id="forecast-spot">{select_options(D['spots'])}</select></label><button type="submit" class="button primary">Actualizar previsión</button></form><p id="forecast-status" role="status" aria-live="polite">Selecciona un spot y actualiza la previsión.</p><div class="forecast-values" aria-busy="false"><article><span>Altura de ola</span><strong id="wave-height">—</strong><small>Altura significativa</small></article><article><span>Periodo</span><strong id="wave-period">—</strong><small>Segundos entre olas</small></article><article><span>Dirección del oleaje</span><strong id="wave-direction">—</strong><small>Procedencia</small></article><article><span>Viento</span><strong id="wind-speed">—</strong><small id="wind-direction">Nudos · procedencia</small></article></div><div class="forecast-table-panel"><h2>Las próximas horas.</h2><div class="table-scroll"><table class="forecast-table"><caption>Previsión horaria en Atlantic/Canary</caption><thead><tr><th>Hora</th><th>Ola (m)</th><th>Periodo (s)</th><th>Oleaje</th><th>Viento (kn)</th></tr></thead><tbody id="forecast-rows"><tr><td colspan="5">Los datos aparecerán al consultar la previsión.</td></tr></tbody></table></div></div><div class="forecast-notes"><p>La altura significativa en mar abierto no equivale a la altura de la ola que rompe en la playa. Comprueba también las condiciones locales.</p><p>Fuente: {source('https://open-meteo.com/','Open-Meteo')} · Modelos marinos, incluido {source('https://www.dwd.de/','DWD')}. Información orientativa para la práctica deportiva.</p><a class="underlink" href="articulos/leer-la-prevision.html">Cómo interpretar estos datos</a></div></section>'''
page('prevision.html','Previsión de oleaje y viento',body,'Previsión actualizada de oleaje, periodo, dirección de las olas y viento para spots de Canarias con Open-Meteo.','prevision.html')

body=intro('COMPETICIÓN Y CULTURA DEL MAR','Apunta la próxima cita.','Fechas anunciadas, eventos a seguir y proyectos en desarrollo. Consulta siempre la última información de la organización.')+f'''<section class="section container"><div class="agenda-layout"><div><div class="event-filter"><label>Filtrar por isla<select id="event-island"><option value="">Todas</option>{select_options(D['islands'])}</select></label><label>Modalidad<select id="event-sport"><option value="">Todas</option>{select_options(D['sports'])}</select></label></div><div class="event-list">{''.join(event_card(e) for e in D['events'])}</div><p id="event-empty" class="info-panel" hidden>No hay eventos con esos filtros.</p></div><aside class="calendar-panel"><div class="calendar-top"><button id="calendar-prev" aria-label="Mes anterior">‹</button><h2 id="calendar-label">Octubre 2026</h2><button id="calendar-next" aria-label="Mes siguiente">›</button></div><div class="calendar-weekdays" aria-hidden="true"><span>L</span><span>M</span><span>X</span><span>J</span><span>V</span><span>S</span><span>D</span></div><div id="calendar-days"></div><p class="calendar-legend"><span aria-hidden="true"></span>Ventana anunciada</p><p id="calendar-status" role="status">Se muestran únicamente fechas confirmadas por la organización.</p><a class="underlink" href="campeonatos.html">Calendarios federativos</a></aside></div></section>'''
page('eventos.html','Eventos y calendario',body,'Agenda de eventos de surf y deportes náuticos en Canarias: Frontón King, Las Américas Pro, Quemao Class y proyecto LWF2027.','eventos.html')
for e in D['events']:
    link=e['source'];internal=link.startswith('proyectos')
    body=intro(e['category'].upper(),e['name'],e['place'],True)+f'<section class="section container event-detail"><div><span class="tag tag-orange">{e["status"]}</span><h2>{e["dateLabel"]}</h2><p class="lead">{e["text"]}</p><p>Consulta el programa, las jornadas, los resultados y las indicaciones de acceso en el canal de la organización. Los horarios de una competición en el mar pueden variar según las condiciones.</p><div class="actions">{button(link,"Conocer el proyecto" if internal else "Consultar organización","primary",not internal)}{button("eventos.html","Volver a la agenda","outline")}</div>'+(f'<button class="underlink calendar-download" data-event="{e["id"]}">Añadir ventana al calendario</button><p class="micro">El archivo incluye la ventana completa, no garantiza competición todos los días.</p>' if e['start'] else '')+f'</div><aside class="info-panel"><h3>Información de referencia</h3><dl class="facts"><div><dt>Territorio</dt><dd>{ISLANDS[e["island"]]["name"]}</dd></div><div><dt>Disciplina</dt><dd>{e["category"]}</dd></div><div><dt>Revisión</dt><dd>8 octubre 2026</dd></div></dl><p>Surf Islas Canarias ofrece información y difusión. Para inscripciones y condiciones de participación, consulta a la organización del evento.</p></aside></section>'
    page(f'eventos/{e["id"]}.html',e['name'],body,e['text'],'eventos.html')

categories=[('Elite / Pro Surf','Pruebas de alto nivel y circuitos internacionales.'),('Campeonatos de España','Calendarios y convocatorias de la federación española.'),('Junior','Competiciones de cantera y categorías juveniles.'),('Kids','Encuentros y competiciones para los más jóvenes.'),('Bodyboard','Competiciones de bodyboard y seguimiento del circuito.'),('Longboard','Eventos dedicados al surf de tabla larga.'),('SUP','Stand Up Paddle de olas y de competición.'),('Eventos especiales','Festivales, cultura y encuentros de comunidad.'),('En espera','Pruebas sujetas a ventana o a nueva confirmación.')]
